"""FastAPI application with REST routes and SPA serving."""

from pathlib import Path

from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse

from settle.db import (
    count_expenses_for_group,
    create_expense,
    create_group,
    delete_group,
    get_group_members,
    init_db,
    list_expenses,
    list_groups,
    rename_group,
)
from settle.ledger import calculate_balances, settle as compute_settlement
from settle.models import CreateExpense, CreateGroup, SettlementResponse

app = FastAPI(title="Settle")

# Initialize in-memory database on startup
init_db(":memory:")

STATIC_DIR = Path(__file__).parent / "static"


@app.get("/")
def serve_spa():
    return FileResponse(STATIC_DIR / "index.html")


@app.post("/api/groups", status_code=201)
def create_group_route(body: CreateGroup):
    gid = create_group(body.name, body.members)
    return {"id": gid, "name": body.name}


@app.get("/api/groups")
def list_groups_route():
    return list_groups()


@app.put("/api/groups/{group_id}")
def rename_group_route(group_id: int, body: CreateGroup):
    try:
        rename_group(group_id, body.name)
    except ValueError:
        raise HTTPException(status_code=404, detail="Group not found")
    return {"id": group_id, "name": body.name}


@app.delete("/api/groups/{group_id}", status_code=204)
def delete_group_route(group_id: int):
    try:
        expense_count = count_expenses_for_group(group_id)
    except ValueError:
        raise HTTPException(status_code=404, detail="Group not found")
    if expense_count > 0:
        raise HTTPException(status_code=409, detail="group has expenses")
    delete_group(group_id)


@app.post("/api/expenses", status_code=201)
def create_expense_route(body: CreateExpense):
    members = get_group_members(body.group_id)

    # Validate payer is a member
    if body.payer not in members:
        raise HTTPException(
            status_code=400,
            detail=f"Payer '{body.payer}' is not a member of group {body.group_id}",
        )

    # Validate all split_among members exist and no duplicates
    seen: set[str] = set()
    for name in body.split_among:
        if name not in members:
            raise HTTPException(
                status_code=400,
                detail=f"'{name}' is not a member of group {body.group_id}",
            )
        if name in seen:
            raise HTTPException(
                status_code=400,
                detail=f"Duplicate member '{name}' in split_among",
            )
        seen.add(name)

    amount_cents = int(round(body.amount * 100))
    eid = create_expense(
        group_id=body.group_id,
        payer=body.payer,
        amount_cents=amount_cents,
        description=body.description,
        split_among=body.split_among,
    )
    return {
        "id": eid,
        "group_id": body.group_id,
        "payer": body.payer,
        "amount_cents": amount_cents,
        "description": body.description,
    }


@app.get("/api/groups/{group_id}/expenses")
def list_expenses_route(group_id: int):
    try:
        return list_expenses(group_id)
    except ValueError:
        raise HTTPException(status_code=404, detail="Group not found")


@app.get("/api/groups/{group_id}/settlement")
def settlement_route(group_id: int):
    try:
        expenses = list_expenses(group_id)
    except ValueError:
        raise HTTPException(status_code=404, detail="Group not found")

    balances = calculate_balances(expenses)
    payments = compute_settlement(balances)
    return SettlementResponse(payments=payments).model_dump()

"""
Tests for settle.ledger — pure settlement algorithm.
"""

import pytest
from settle.ledger import calculate_balances, settle
from settle.models import Payment

# ── helpers ───────────────────────────────────────────────────────────────

def _exp(payer: str, amount_cents: int, split_among: list[str]) -> dict:
    return {"payer": payer, "amount_cents": amount_cents, "split_among": split_among}

# ── calculate_balances ───────────────────────────────────────────────────

class TestCalculateBalances:
    def test_single_expense_two_members(self):
        expenses = [_exp("Alice", 3000, ["Alice", "Bob"])]
        assert calculate_balances(expenses) == {"Alice": 1500, "Bob": -1500}

    def test_single_expense_three_members(self):
        expenses = [_exp("Alice", 3000, ["Alice", "Bob", "Charlie"])]
        assert calculate_balances(expenses) == {"Alice": 2000, "Bob": -1000, "Charlie": -1000}

    def test_uneven_split_remainder(self):
        # 100 cents split among 3 → shares of 34, 33, 33
        expenses = [_exp("Alice", 100, ["Alice", "Bob", "Charlie"])]
        assert calculate_balances(expenses) == {"Alice": 66, "Bob": -33, "Charlie": -33}

    def test_multiple_expenses_accumulate(self):
        expenses = [
            _exp("Alice", 3000, ["Alice", "Bob"]),
            _exp("Bob", 2000, ["Alice", "Bob"]),
        ]
        # Alice: +3000 -1500 +2000 -1000 = 2500
        # Bob:   -1500 +3000 -2000 +1000 = 500
        # Wait, let me recalculate:
        # Exp1: Alice pays 3000, split [Alice, Bob]
        #   Alice: +3000 -1500 = 1500
        #   Bob:   -1500
        # Exp2: Bob pays 2000, split [Alice, Bob]
        #   Alice: +1500 -1000 = 500
        #   Bob:   -1500 +2000 -1000 = -500
        assert calculate_balances(expenses) == {"Alice": 500, "Bob": -500}

    def test_payer_not_in_split_among(self):
        # Alice pays for Bob and Charlie only
        expenses = [_exp("Alice", 2000, ["Bob", "Charlie"])]
        assert calculate_balances(expenses) == {"Alice": 2000, "Bob": -1000, "Charlie": -1000}

    def test_empty_expenses(self):
        assert calculate_balances([]) == {}

# ── settle ───────────────────────────────────────────────────────────────

class TestSettle:
    def test_simple_two_person(self):
        balances = {"Alice": 1500, "Bob": -1500}
        payments = settle(balances)
        assert len(payments) == 1
        p = payments[0]
        assert p.from_ == "Bob"
        assert p.to == "Alice"
        assert p.amount_cents == 1500

    def test_three_person_minimised(self):
        # Alice is owed 2000, Bob owes 1000, Charlie owes 1000
        balances = {"Alice": 2000, "Bob": -1000, "Charlie": -1000}
        payments = settle(balances)
        assert len(payments) == 2
        amounts = {p.from_: p.amount_cents for p in payments}
        assert amounts["Bob"] == 1000
        assert amounts["Charlie"] == 1000
        for p in payments:
            assert p.to == "Alice"

    def test_zero_balances_produce_no_payments(self):
        balances = {"Alice": 0, "Bob": 0}
        assert settle(balances) == []

    def test_empty_balances(self):
        assert settle({}) == []

    def test_complex_four_person(self):
        # Alice +3000, Bob -1500, Charlie -1000, Dave -500
        balances = {"Alice": 3000, "Bob": -1500, "Charlie": -1000, "Dave": -500}
        payments = settle(balances)
        assert len(payments) == 3
        # Verify total outflow matches total inflow
        total_in = sum(p.amount_cents for p in payments if p.to == "Alice")
        total_out = sum(p.amount_cents for p in payments)
        assert total_in == 3000
        assert total_out == 3000

    def test_payment_model_fields(self):
        balances = {"X": 100, "Y": -100}
        payments = settle(balances)
        p = payments[0]
        assert isinstance(p, Payment)
        assert hasattr(p, "from_")
        assert hasattr(p, "to")
        assert hasattr(p, "amount_cents")

    def test_balances_sum_to_zero(self):
        # After settlement, all balances should be zeroed
        expenses = [
            _exp("Alice", 3000, ["Alice", "Bob", "Charlie"]),
            _exp("Bob", 1500, ["Alice", "Charlie"]),
        ]
        balances = calculate_balances(expenses)
        assert sum(balances.values()) == 0
        payments = settle(balances)
        # Verify settlement zeroes out balances
        remaining = dict(balances)
        for p in payments:
            remaining[p.from_] += p.amount_cents  # debtor pays → balance rises
            remaining[p.to] -= p.amount_cents     # creditor receives → balance falls
        assert all(v == 0 for v in remaining.values())
